const $=s=>document.querySelector(s), canvas=$('#canvas'),ctx=canvas.getContext('2d');
const KEY='frame-lab-project-v1';
let project={version:1,format:'explainer',idea:'Why small habits make a big difference',duration:30,palette:'mint',captions:'clean',scenes:[{title:'Small moves. Big change.',text:'A tiny habit can make a bigger difference than one burst of motivation.',visual:'orbits'},{title:'Make it easy to start.',text:'Choose something small enough to do even on a busy day.',visual:'steps'},{title:'Build on what you already do.',text:'After making your coffee, take one minute to plan your next step.',visual:'rings'},{title:'Start small. Repeat tomorrow.',text:'What is one small action you could try today?',visual:'orbits'}]};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(valid(saved))project=saved}catch{}
function valid(p){return p&&p.version===1&&['explainer','story','loop'].includes(p.format)&&[15,30,60].includes(p.duration)&&['mint','sunset','blue'].includes(p.palette)&&['clean','bold','none'].includes(p.captions)&&typeof p.idea==='string'&&p.idea.length<=180&&Array.isArray(p.scenes)&&p.scenes.length>0&&p.scenes.length<=8&&p.scenes.every(s=>typeof s.title==='string'&&s.title.length<=100&&typeof s.text==='string'&&s.text.length<=400&&['orbits','steps','rings','character'].includes(s.visual))}
