function status(s){$('#status').textContent=s}function save(){try{localStorage.setItem(KEY,JSON.stringify(project))}catch{status('Browser storage is full. Save project JSON to keep your work.')}}
function sync(){for(const id of ['idea','duration','palette','captions'])$('#'+id).value=project[id];document.querySelectorAll('[data-format]').forEach(b=>b.classList.toggle('selected',b.dataset.format===project.format));$('#seek').max=project.duration;renderScenes();draw();}
function field(tag,value,max){const e=document.createElement(tag);e.value=value;e.maxLength=max;return e}
function renderScenes(){const host=$('#scenes');host.replaceChildren();project.scenes.forEach((scene,i)=>{const card=document.createElement('div');card.className='scene';const top=document.createElement('div');top.className='scene-top';const label=document.createElement('span');label.textContent=`SCENE ${String(i+1).padStart(2,'0')} · ${(project.duration/project.scenes.length).toFixed(1)} SEC`;top.append(label);const actions=document.createElement('div');for(const [symbol,action] of [['↑',()=>{if(i){[project.scenes[i-1],project.scenes[i]]=[scene,project.scenes[i-1]];save();sync()}}],['×',()=>{if(project.scenes.length>1){project.scenes.splice(i,1);save();sync()}}]]){const b=document.createElement('button');b.textContent=symbol;b.setAttribute('aria-label',symbol==='↑'?'Move scene up':'Remove scene');b.onclick=action;actions.append(b)}top.append(actions);const title=field('input',scene.title,100);title.setAttribute('aria-label',`Scene ${i+1} title`);const text=field('textarea',scene.text,400);text.setAttribute('aria-label',`Scene ${i+1} narration`);title.oninput=()=>{scene.title=title.value;save();draw()};text.oninput=()=>{scene.text=text.value;save();draw()};const select=document.createElement('select');select.setAttribute('aria-label',`Scene ${i+1} animation`);for(const [v,n] of [['orbits','Floating shapes'],['steps','Rising steps'],['rings','Ripple loop'],['character','Character animation']])select.add(new Option(n,v));select.value=scene.visual;select.onchange=()=>{scene.visual=select.value;save();draw()};card.append(top,title,text,select);host.append(card)})}
for(const id of ['idea','duration','palette','captions'])$('#'+id).addEventListener('input',e=>{project[id]=id==='duration'?Number(e.target.value):e.target.value;if(id==='duration'){stop();time=0;$('#seek').max=project.duration;renderScenes()}save();draw()});
document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{project.format=b.dataset.format;save();sync();status('Format selected. Build storyboard to draft scenes in this format.')});
$('#draft').onclick=()=>{if(!project.idea.trim()){status('Enter a topic or premise first.');return}if(!confirm('Replace these scene cards with a new template draft? Your exported files are unaffected.'))return;stop();time=0;const idea=project.idea.trim();project.scenes=project.format==='explainer'?[{title:idea,text:`What makes ${idea.toLowerCase()} worth understanding? Start with one clear question.`,visual:'orbits'},{title:'The key idea',text:'Write the simplest explanation here. Give your audience one thing to remember.',visual:'steps'},{title:'Show it in action',text:'Add a concrete example that makes the idea easy to understand.',visual:'rings'},{title:'Make it useful',text:'End with an answer or a small action your audience can take.',visual:'orbits'}]:project.format==='story'?[{title:idea,text:'Meet our little explorer. Today, something unexpected is about to happen.',visual:'character'},{title:'A small problem',text:'Describe the obstacle. What does the character want, and what gets in the way?',visual:'character'},{title:'An unexpected turn',text:'Write the choice that changes the story.',visual:'character'},{title:'A new beginning',text:'Resolve the story with a surprise, a laugh, or a small lesson.',visual:'character'}]:[{title:idea,text:'',visual:'rings'}];save();sync();status('Draft ready. Replace the writing prompts with your finished script before exporting.')};
$('#add').onclick=()=>{if(project.scenes.length>=8){status('This prototype supports up to eight scenes.');return}project.scenes.push({title:'Your next scene',text:'',visual:'orbits'});save();sync()};
function stop(){playing=false;audio.pause();$('#play').textContent='▶'}
$('#play').onclick=async()=>{if(playing){stop();return}if(time>=project.duration)time=0;playing=true;last=performance.now();$('#play').textContent='Ⅱ';if(audioUrl){audio.currentTime=time;try{await audio.play()}catch{status('Audio playback was blocked. Click play again.')}}};
$('#seek').oninput=e=>{time=Number(e.target.value);if(audioUrl)audio.currentTime=time;draw()};
$('#audio').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024){status('Please use an audio file under 100 MB.');return}stop();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(file);audio.src=audioUrl;audio.load();$('#audio-name').textContent=file.name+' · Reattach audio when reopening the project.';audio.onerror=()=>{status('This audio format could not be decoded. Try MP3 or WAV.');clearAudio()}};
function clearAudio(){stop();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;audio.removeAttribute('src');$('#audio').value='';$('#audio-name').textContent='No narration attached. Export will be silent.'}$('#clear-audio').onclick=clearAudio;
const colors={mint:['#14231f','#c9efaa','#5cae94'],sunset:['#291c30','#ffbb8f','#b179c9'],blue:['#111f38','#a9d5ff','#5a7bfa']};
function wrap(text,max,font){ctx.font=font;const words=text.split(/\s+/).filter(Boolean),lines=[];let line='';for(const word of words){if(ctx.measureText((line+' '+word).trim()).width>max&&line){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);return lines}
function textFit(text,y,size,maxHeight,color,weight='700'){let lines;do{lines=wrap(text,590,`${weight} ${size}px sans-serif`);if(lines.length*size*1.2<=maxHeight)break;size-=2}while(size>18);ctx.fillStyle=color;ctx.font=`${weight} ${size}px sans-serif`;ctx.textAlign='center';lines.forEach((line,i)=>ctx.fillText(line,360,y+i*size*1.2));return lines.length*size*1.2}
function draw(){const [bg,accent,secondary]=colors[project.palette],index=Math.min(project.scenes.length-1,Math.floor(time/project.duration*project.scenes.length)),scene=project.scenes[index],local=(time-index*project.duration/project.scenes.length)/(project.duration/project.scenes.length);ctx.fillStyle=bg;ctx.fillRect(0,0,720,1280);ctx.fillStyle=accent;ctx.globalAlpha=.08;for(let x=30;x<720;x+=40)for(let y=30;y<1280;y+=40){ctx.beginPath();ctx.arc(x,y,1.5,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.font='18px sans-serif';ctx.textAlign='left';ctx.fillStyle=accent;ctx.fillText(project.format==='story'?'LITTLE STORIES':project.format==='loop'?'MOMENT OF MOTION':'ONE GOOD IDEA',54,80);ctx.textAlign='right';ctx.fillText(`${String(index+1).padStart(2,'0')} / ${String(project.scenes.length).padStart(2,'0')}`,666,80);
textFit(scene.title,175,60,225,accent);const phase=local*Math.PI*2;ctx.save();ctx.translate(360,650);
if(scene.visual==='rings'){for(let i=5;i>=1;i--){ctx.strokeStyle=i%2?accent:secondary;ctx.lineWidth=18;ctx.beginPath();ctx.ellipse(0,0,35+i*29,35+i*29*(.65+.25*Math.cos(phase)),phase*.5+i*.15,0,Math.PI*2);ctx.stroke()}}
else if(scene.visual==='steps'){for(let i=0;i<5;i++){const h=60+i*40+Math.sin(phase+i)*15;ctx.fillStyle=i%2?secondary:accent;ctx.beginPath();ctx.roundRect(-230+i*96,130-h,72,h,12);ctx.fill()}ctx.strokeStyle=accent;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-240,150);ctx.lineTo(240,150);ctx.stroke()}
else if(scene.visual==='character'){ctx.translate(0,Math.sin(phase)*20);ctx.fillStyle=secondary;ctx.beginPath();ctx.ellipse(0,180,145,22,0,0,Math.PI*2);ctx.globalAlpha=.3;ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=accent;ctx.beginPath();ctx.roundRect(-105,-125,210,270,65);ctx.fill();ctx.fillStyle=bg;for(const x of [-38,38]){ctx.beginPath();ctx.ellipse(x,-35,11,16,0,0,Math.PI*2);ctx.fill()}ctx.strokeStyle=bg;ctx.lineWidth=7;ctx.beginPath();ctx.arc(0,5,28,0,Math.PI);ctx.stroke();ctx.strokeStyle=accent;ctx.lineWidth=22;ctx.lineCap='round';for(const sign of [-1,1]){ctx.beginPath();ctx.moveTo(sign*100,30);ctx.lineTo(sign*155,-15+Math.sin(phase)*30);ctx.stroke();ctx.beginPath();ctx.moveTo(sign*50,140);ctx.lineTo(sign*65,180);ctx.stroke()}}
else{ctx.strokeStyle=secondary;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,180,0,Math.PI*2);ctx.stroke();ctx.fillStyle=accent;ctx.save();ctx.rotate(phase*.5);ctx.beginPath();ctx.roundRect(-90,-90,180,180,45);ctx.fill();ctx.restore();for(let i=0;i<3;i++){const a=phase+i*2*Math.PI/3;ctx.fillStyle=i%2?accent:secondary;ctx.beginPath();ctx.arc(Math.cos(a)*180,Math.sin(a)*180,22+i*8,0,Math.PI*2);ctx.fill()}}ctx.restore();
if(project.captions!=='none'&&scene.text){const words=scene.text.replace(/>>\s*/g,'').split(/\s+/).filter(Boolean);const groups=[];for(let i=0;i<words.length;i+=7)groups.push(words.slice(i,i+7).join(' '));const caption=groups[Math.min(groups.length-1,Math.floor(local*groups.length))]||'';if(project.captions==='bold'){ctx.fillStyle=accent;ctx.beginPath();ctx.roundRect(42,960,636,150,22);ctx.fill()}textFit(caption,1017,40,125,project.captions==='bold'?bg:'#ffffff','600')}
ctx.fillStyle=secondary;ctx.fillRect(54,1195,612,4);ctx.fillStyle=accent;ctx.fillRect(54,1195,612*time/project.duration,4);$('#seek').value=time;$('#time').textContent=`${clock(time)} / ${clock(project.duration)}`}
function clock(s){return `${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`}
function tick(now){if(playing){time+=Math.max(0,now-last)/1000;if(time>=project.duration){time=project.duration;stop();if(recording&&recorder.state==='recording')recorder.stop()}}last=now;draw();requestAnimationFrame(tick)}requestAnimationFrame(tick);
function lock(value){document.querySelectorAll('.editor input,.editor button,.editor textarea,.editor select,.secondary-actions button,.secondary-actions input,#play,#seek,#export').forEach(e=>e.disabled=value);$('#cancel').hidden=!value}
$('#export').onclick=async()=>{if(!window.MediaRecorder||!canvas.captureStream){status('Video export is unavailable in this browser. Try Chrome.');return}stop();recording=true;exportCancelled=false;lock(true);time=0;draw();try{const stream=canvas.captureStream(30);if(audioUrl){if(!audioContext){audioContext=new AudioContext();audioSource=audioContext.createMediaElementSource(audio);audioDest=audioContext.createMediaStreamDestination();audioSource.connect(audioDest);audioSource.connect(audioContext.destination)}await audioContext.resume();audioDest.stream.getAudioTracks().forEach(t=>stream.addTrack(t));audio.currentTime=0;await audio.play()}const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw Error('WebM recording is unsupported. Try Chrome.');const chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:4000000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=()=>{exportCancelled=true;status('Recording failed. Try again in Chrome.');if(recorder.state!=='inactive')recorder.stop()};recorder.onstop=()=>{stop();recording=false;lock(false);stream.getVideoTracks().forEach(t=>t.stop());if(!exportCancelled){download(new Blob(chunks,{type:mime}),'frame-lab-'+project.format+'.webm');status('Video exported. Your editable project is saved in this browser.')}else status('Export cancelled. Your project is unchanged.')};recorder.start(250);playing=true;last=performance.now();status(`Rendering ${project.duration} seconds. Keep this tab visible…`)}catch(e){recording=false;stop();lock(false);status('Export failed: '+e.message)}};
$('#cancel').onclick=()=>{exportCancelled=true;if(recorder?.state==='recording')recorder.stop()};document.addEventListener('visibilitychange',()=>{if(document.hidden&&recording){exportCancelled=true;if(recorder?.state==='recording')recorder.stop();status('Export cancelled because the tab was hidden. Keep it visible for the full render.')}});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('#save').onclick=()=>download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),'frame-lab-project.json');
$('#import').onchange=async e=>{if(recording)return;try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Project file is too large.');const p=JSON.parse(await file.text());if(!valid(p))throw Error('This is not a supported Frame Lab project.');stop();clearAudio();project=p;time=0;save();sync();status('Project imported. Reattach narration if needed.')}catch(error){status(error.message)}finally{e.target.value=''}};
